<?php
require_once __DIR__ . '/../includes/functions.php';
$user=require_role(['admin']);$type=$_GET['type']??'item';$id=(int)($_GET['id']??0);$config=['item'=>['table'=>'menu_items','tab'=>'menu','title'=>'Edit menu item'],'table'=>['table'=>'restaurant_tables','tab'=>'tables','title'=>'Edit table'],'category'=>['table'=>'categories','tab'=>'menu','title'=>'Edit category']];
if(!isset($config[$type])||$id<1){http_response_code(404);exit('Not found.');}$cfg=$config[$type];$stmt=db()->prepare('SELECT * FROM '.$cfg['table'].' WHERE id=?');$stmt->execute([$id]);$record=$stmt->fetch();if(!$record){http_response_code(404);exit('Not found.');}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check();
 try{
  if($type==='item'){$name=trim($_POST['name']??'');$category=(int)($_POST['category_id']??0);$price=(float)($_POST['price']??0);$photo=trim($_POST['photo_url']??'');$description=trim($_POST['description']??'');if($name===''||$category<1||$price<=0)throw new RuntimeException('Enter a dish name, category, and positive price.');if($photo!==''&&!preg_match('~^(https?://|/|\.\./)~i',$photo))throw new RuntimeException('Photo must use an http(s) URL or a local path.');db()->prepare('UPDATE menu_items SET category_id=?,name=?,description=?,price=?,photo_url=?,is_available=? WHERE id=?')->execute([$category,$name,$description,$price,$photo,isset($_POST['is_available'])?1:0,$id]);}
  elseif($type==='table'){$number=trim($_POST['table_number']??'');$seats=(int)($_POST['seats']??0);if($number===''||$seats<1||$seats>30)throw new RuntimeException('Enter a table number and a seat count from 1 to 30.');db()->prepare('UPDATE restaurant_tables SET table_number=?,seats=?,is_active=? WHERE id=?')->execute([$number,$seats,isset($_POST['is_active'])?1:0,$id]);}
  else{$name=trim($_POST['name']??'');$description=trim($_POST['description']??'');if($name==='')throw new RuntimeException('Category name is required.');db()->prepare('UPDATE categories SET name=?,description=?,sort_order=?,is_active=? WHERE id=?')->execute([$name,$description,(int)($_POST['sort_order']??0),isset($_POST['is_active'])?1:0,$id]);}
  flash($cfg['title'].' saved.');redirect('index.php?tab='.$cfg['tab']);
 }catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Could not save. Check that the name is unique and try again.';}
}
$pageTitle=$cfg['title'];require __DIR__ . '/../includes/header.php';
?>
