<?php if($type==='item'):$categories=db()->query('SELECT id,name FROM categories ORDER BY sort_order,name')->fetchAll();?><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Dish name<input name="name" value="<?= e($record['name']) ?>" required></label><label>Category<select name="category_id" required><?php foreach($categories as $cat): ?><option value="<?= (int)$cat['id'] ?>" <?= (int)$record['category_id']===(int)$cat['id']?'selected':'' ?>><?= e($cat['name']) ?></option><?php endforeach; ?></select></label><label>Price (MMK)<input type="number" name="price" min="1" step="1" value="<?= e((string)$record['price']) ?>" required></label><label>Photo URL<input name="photo_url" value="<?= e($record['photo_url']) ?>"></label><label>Description<textarea name="description" rows="4"><?= e($record['description']) ?></textarea></label><label class="check-label"><input type="checkbox" name="is_available" <?= $record['is_available']?'checked':'' ?>> Available to order</label><button class="button button-dark">Save menu item</button></form>
<?php elseif($type==='table'): ?><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Table number<input name="table_number" value="<?= e($record['table_number']) ?>" required></label><label>Seats<input type="number" name="seats" min="1" max="30" value="<?= (int)$record['seats'] ?>" required></label><label class="check-label"><input type="checkbox" name="is_active" <?= $record['is_active']?'checked':'' ?>> Table is active for reservations</label><button class="button button-dark">Save table</button></form>
<?php else: ?><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Category name<input name="name" value="<?= e($record['name']) ?>" required></label><label>Description<input name="description" value="<?= e($record['description']) ?>"></label><label>Sort order<input type="number" name="sort_order" value="<?= (int)$record['sort_order'] ?>"></label><label class="check-label"><input type="checkbox" name="is_active" <?= $record['is_active']?'checked':'' ?>> Category is visible on menu</label><button class="button button-dark">Save category</button></form><?php endif; ?>
